    static final long MOD = 998244353L;

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        int maxN = s + p + 5;
        long[] fact = new long[maxN];
        long[] invFact = new long[maxN];
        fact[0] = 1;
        for (int i = 1; i < maxN; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[maxN - 1] = modPow(fact[maxN - 1], MOD - 2);
        for (int i = maxN - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        long totalStates = 0;
        long winStates = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            if (rem < 0) break;

            long totalRem = comb(rem + p - 2, p - 2, fact, invFact);

            long winForThisA1 = 0;
            for (int m = 0; m <= a1; m++) {
                int sumRem = rem;
                int maxOthers = a1;
                int maxVal = maxOthers - m;
                if (maxVal < 0) continue;

                long ways = 0;
                for (int k = 0; k <= p - 1; k++) {
                    long sign = (k % 2 == 0) ? 1 : MOD - 1;
                    int s2 = sumRem - k * (maxVal + 1);
                    if (s2 < 0) break;
                    long add = comb(p - 1, k, fact, invFact) * comb(s2 + p - 2, p - 2, fact, invFact) % MOD;
                    ways = (ways + sign * add) % MOD;
                }
                if (ways == 0) continue;

                long tieCount = 1;
                if (m == a1) {
                    tieCount = 1;
                } else {
                    int maxTieOthers = Math.min(p - 1, sumRem / m);
                    long sumInv = 0;
                    for (int t = 0; t <= maxTieOthers; t++) {
                        int sumRest = sumRem - t * m;
                        if (sumRest < 0) break;
                        long waysTie = comb(p - 1, t, fact, invFact);
                        long waysRest = 0;
                        for (int k = 0; k <= p - 1 - t; k++) {
                            long sign = (k % 2 == 0) ? 1 : MOD - 1;
                            int s2 = sumRest - k * (maxVal);
                            if (s2 < 0) break;
                            long add = comb(p - 1 - t, k, fact, invFact) * comb(s2 + p - 2, p - 2, fact, invFact) % MOD;
                            waysRest = (waysRest + sign * add) % MOD;
                        }
                        if (waysRest == 0) continue;
                        long invTplus1 = modPow(t + 1, MOD - 2);
                        long contrib = waysTie * waysRest % MOD * invTplus1 % MOD;
                        sumInv = (sumInv + contrib) % MOD;
                    }
                    tieCount = sumInv;
                }

                winForThisA1 = (winForThisA1 + ways * tieCount) % MOD;
            }

            totalStates = (totalStates + totalRem) % MOD;
            winStates = (winStates + winForThisA1) % MOD;
        }

        if (totalStates == 0) {
            System.out.println(0);
            return;
        }
        long ans = winStates * modPow(totalStates, MOD - 2) % MOD;
        System.out.println(ans);
    }

    static long comb(int n, int k, long[] fact, long[] invFact) {
        if (n < 0 || k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    // Simple fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
