    static final long MOD = 998244353L;
    static int MAXS = 5000;
    static long[] fact = new long[MAXS + 5];
    static long[] invFact = new long[MAXS + 5];

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static long inv(long x) {
        return modPow(x, MOD - 2);
    }

    static void precomputeFact(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = inv(fact[n]);
        for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    }

    static long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        precomputeFact(s + p + 5);

        long totalStates = 0;
        long winStates = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            // number of states for others: compositions of rem into p-1 nonnegative parts
            long statesOthers = comb(rem + p - 2, p - 2);
            if (statesOthers == 0) continue;
            totalStates = (totalStates + statesOthers) % MOD;

            long winForThisA1 = 0;
            // iterate maximum score M among others
            for (int M = 0; M <= rem; M++) {
                int maxOthers = M;
                if (maxOthers > a1) continue; // Hasan can't win
                long waysMaxEqM = 0;
                if (M == 0) {
                    // all others zero
                    if (rem == 0) waysMaxEqM = 1;
                } else {
                    // count sequences with max exactly M
                    long totalMaxLeM = 0;
                    long totalMaxLeMminus1 = 0;
                    // compositions with each part <= M
                    for (int k = 0; k <= p - 1; k++) {
                        int sign = (k % 2 == 0) ? 1 : -1;
                        long c = comb(p - 1, k);
                        int val = rem - k * (M + 1);
                        if (val < 0) break;
                        long add = c * comb(val + p - 2, p - 2) % MOD;
                        if (sign == 1) totalMaxLeM = (totalMaxLeM + add) % MOD;
                        else {
                            totalMaxLeM -= add;
                            if (totalMaxLeM < 0) totalMaxLeM += MOD;
                        }
                    }
                    if (M - 1 >= 0) {
                        for (int k = 0; k <= p - 1; k++) {
                            int sign = (k % 2 == 0) ? 1 : -1;
                            long c = comb(p - 1, k);
                            int val = rem - k * M;
                            if (val < 0) break;
                            long add = c * comb(val + p - 2, p - 2) % MOD;
                            if (sign == 1) totalMaxLeMminus1 = (totalMaxLeMminus1 + add) % MOD;
                            else {
                                totalMaxLeMminus1 -= add;
                                if (totalMaxLeMminus1 < 0) totalMaxLeMminus1 += MOD;
                            }
                        }
                    }
                    waysMaxEqM = totalMaxLeM - totalMaxLeMminus1;
                    waysMaxEqM %= MOD;
                    if (waysMaxEqM < 0) waysMaxEqM += MOD;
                }

                if (waysMaxEqM == 0) continue;

                if (maxOthers < a1) {
                    winForThisA1 = (winForThisA1 + waysMaxEqM) % MOD;
                } else { // tie
                    // count sequences where exactly t others have score a1 (M=a1)
                    int Mtie = a1;
                    if (Mtie > rem) continue;
                    long tieWays = 0;
                    for (int t = 1; t <= p - 1; t++) {
                        // choose t players with score a1
                        long chooseT = comb(p - 1, t);
                        int rem2 = rem - t * Mtie;
                        if (rem2 < 0) break;
                        // remaining p-1-t players have scores in [0, Mtie-1]
                        long waysRem = 0;
                        if (Mtie == 0) {
                            if (rem2 == 0) waysRem = 1;
                        } else {
                            for (int k = 0; k <= p - 1 - t; k++) {
                                int sign = (k % 2 == 0) ? 1 : -1;
                                long c = comb(p - 1 - t, k);
                                int val = rem2 - k * Mtie;
                                if (val < 0) break;
                                long add = c * comb(val + p - 2 - t, p - 2 - t) % MOD;
                                if (sign == 1) waysRem = (waysRem + add) % MOD;
                                else {
                                    waysRem -= add;
                                    if (waysRem < 0) waysRem += MOD;
                                }
                            }
                        }
                        if (waysRem == 0) continue;
                        long probWin = inv(t + 1);
                        long addTie = chooseT * waysRem % MOD * probWin % MOD;
                        tieWays = (tieWays + addTie) % MOD;
                    }
                    winForThisA1 = (winForThisA1 + tieWays) % MOD;
                }
            }
            winStates = (winStates + winForThisA1) % MOD;
        }

        long ans;
        if (totalStates == 0) ans = 0;
        else ans = winStates * inv(totalStates) % MOD;
        System.out.println(ans);
    }

