    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        precomputeFact(s + p + 5);

        long totalStates = 0;
        long winStates = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            if (rem < 0) break;

            // total states for this a1: compositions of rem into p-1 nonnegative parts
            long totalForA1 = comb(rem + p - 2, p - 2);
            if (totalForA1 == 0) continue;
            totalStates = (totalStates + totalForA1) % MOD;

            long winForA1 = 0;

            // max possible score among others is rem (if one takes all)
            for (int m = 0; m <= rem; m++) {
                int othersRem = rem - m;
                if (othersRem < 0) break;

                // count states where max of others is exactly m
                long cntMaxEqM = 0;

                // inclusion-exclusion over players whose score > m
                int maxK = rem / (m + 1);
                for (int k = 0; k <= maxK && k <= p - 1; k++) {
                    int sign = (k % 2 == 0) ? 1 : -1;
                    int rem2 = rem - k * (m + 1);
                    if (rem2 < 0) continue;
                    long ways = comb(p - 1, k) * comb(rem2 + p - 2, p - 2) % MOD;
                    if (sign == 1) {
                        cntMaxEqM = (cntMaxEqM + ways) % MOD;
                    } else {
                        cntMaxEqM = (cntMaxEqM - ways) % MOD;
                        if (cntMaxEqM < 0) cntMaxEqM += MOD;
                    }
                }

                if (cntMaxEqM == 0) continue;

                if (m < a1) {
                    // Hasan strictly greater than max of others
                    winForA1 = (winForA1 + cntMaxEqM) % MOD;
                } else if (m == a1) {
                    // tie on max score a1
                    // number of players (including Hasan) with score a1
                    // others: number of players with score exactly m
                    // we need expected 1/(t) where t is number of top scorers
                    // but all top scorers have score a1; Hasan is one of them
                    // Among others, let t' be number of players with score m.
                    // Then t = t' + 1, and Hasan's chance is 1/(t'+1).
                    // We need sum over all states of 1/(t'+1).
                    // We compute via DP over others: number of players with score m.

                    // To avoid heavy per-state enumeration, we use combinatorial counting:
                    // For each t' >= 0, count states where exactly t' others have score m
                    // and remaining (p-1 - t') have <= m-1, total sum rem.

                    long tieWin = 0;
                    for (int t = 0; t <= p - 1; t++) {
                        // choose t players to have score m
                        long chooseT = comb(p - 1, t);
                        int rem3 = rem - t * m;
                        if (rem3 < 0) continue;

                        // remaining players (p-1 - t) have scores in [0, m-1]
                        // count number of solutions to sum = rem3 with upper bound m-1
                        long waysBounded = 0;
                        int playersLeft = p - 1 - t;
                        if (playersLeft == 0) {
                            if (rem3 == 0) waysBounded = 1;
                        } else {
                            // inclusion-exclusion for upper bound
                            for (int k = 0; k <= playersLeft; k++) {
                                int sign = (k % 2 == 0) ? 1 : -1;
                                int rem4 = rem3 - k * m;
                                if (rem4 < 0) break;
                                long w = comb(playersLeft, k) * comb(rem4 + playersLeft - 1, playersLeft - 1) % MOD;
                                if (sign == 1) {
                                    waysBounded = (waysBounded + w) % MOD;
                                } else {
                                    waysBounded = (waysBounded - w) % MOD;
                                    if (waysBounded < 0) waysBounded += MOD;
                                }
                            }
                        }
                        if (waysBounded == 0) continue;
                        long states = chooseT * waysBounded % MOD;
                        long prob = inv(t + 1);
                        tieWin = (tieWin + states * prob) % MOD;
                    }
                    winForA1 = (winForA1 + tieWin) % MOD;
                }
            }

            winStates = (winStates + winForA1) % MOD;
        }

        if (totalStates == 0) {
            System.out.println(0);
            return;
        }
        long ans = winStates * inv(totalStates) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    // FastScanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        long[][] C = new long[5010][];
        for (int n = 0; n <= 5000; n++) {
            C[n] = new long[n + 1];
            C[n][0] = C[n][n] = 1;
            for (int k = 1; k < n; k++) {
                C[n][k] = (C[n - 1][k - 1] + C[n - 1][k]) % MOD;
            }
        }

        long[] fact = new long[5010];
        long[] invFact = new long[5010];
        fact[0] = 1;
        for (int i = 1; i <= 5000; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[5000] = modPow(fact[5000], MOD - 2);
        for (int i = 5000; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long totalStates = 0;
        long winStates = 0;

        for (int a1 = r; a1 <= s; a1++) {
            int rem = s - a1;
            if (rem < 0) break;

            long totalForA1 = C[rem + p - 1][p - 1];
            totalStates = (totalStates + totalForA1) % MOD;

            int maxOthers = a1;
            long winForA1 = 0;

            for (int m = 0; m <= maxOthers; m++) {
                int rem2 = rem - (p - 1) * m;
                if (rem2 < 0) break;

                long ways = 0;
                int maxNonZero = p - 1;
                for (int k = 0; k <= maxNonZero; k++) {
                    if (rem2 - k < 0) break;
                    long combPlayers = C[p - 1][k];
                    long combSum = C[rem2 - k + p - 2][p - 2];
                    long sign = (k % 2 == 0) ? 1 : MOD - 1;
                    ways = (ways + sign * combPlayers % MOD * combSum) % MOD;
                }

                int maxTie = p;
                for (int t = 0; t <= maxTie; t++) {
                    if (t > 0 && m != a1) break;
                    if (t == 0 && m == a1) continue;

                    long waysTie;
                    if (t == 0) {
                        waysTie = ways;
                    } else {
                        if (t > p) continue;
                        long chooseTie = C[p][t];
                        long chooseNonTie = (t == p) ? 1 : C[p - t - 1 + (p - t)][p - t];
                        waysTie = chooseTie * chooseNonTie % MOD;
                    }

                    long probWin;
                    if (t == 0) probWin = 1;
                    else probWin = invFact[t] * fact[t - 1] % MOD;

                    winForA1 = (winForA1 + waysTie * probWin) % MOD;
                }
            }

            winStates = (winStates + winForA1) % MOD;
        }

        long invTotal = modPow(totalStates, MOD - 2);
        long ans = winStates * invTotal % MOD;
        System.out.println(ans);
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    // Simple fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
